import React from 'react';

interface PriceDisplayProps {
  price: number;
  discountedPrice?: number;
  currency?: string;
}

function formatPrice(amount: number, currency: string): string {
  // Math.ceil so we never under-charge when fractional cents arise from discount math
  const rounded = Math.ceil(amount * 100) / 100;
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(rounded);
}

export function PriceDisplay({ price, discountedPrice, currency = 'USD' }: PriceDisplayProps): React.ReactElement {
  const hasDiscount = discountedPrice !== undefined && discountedPrice < price;

  return (
    <div className="price-display">
      {hasDiscount ? (
        <>
          <span className="price-display-original" aria-label={`Original price ${formatPrice(price, currency)}`}>
            <s>{formatPrice(price, currency)}</s>
          </span>
          <span className="price-display-discounted" aria-label={`Discounted price ${formatPrice(discountedPrice, currency)}`}>
            {formatPrice(discountedPrice, currency)}
          </span>
        </>
      ) : (
        <span className="price-display-current" aria-label={`Price ${formatPrice(price, currency)}`}>
          {formatPrice(price, currency)}
        </span>
      )}
    </div>
  );
}
